(function(){'use strict';
const V=window.SpareVeileder,$=id=>document.getElementById(id);let selected=null,hasAnswer=false;
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;};
function button(text,fn){const b=el('button',text);b.type='button';b.addEventListener('click',fn);return b;}
function dirty(){if(hasAnswer){$('answer').replaceChildren(el('p','Opplysningene eller temaet er endret. Trykk «Vis vurdering» for å få et nytt svar.','ask-stale'));$('answerTitle').textContent='Vurderingen må oppdateres';hasAnswer=false;} $('changed').textContent='';}
function choose(id){dirty();selected=id;const t=V.topics.find(t=>t.id===id);$('answerButton').disabled=false;$('answerButton').textContent='Vis vurdering: '+t.title;for(const b of document.querySelectorAll('[data-topic]'))b.setAttribute('aria-pressed',String(b.dataset.topic===id));$('fixedField').hidden=id!=='mortgage';$('ownerField').hidden=id!=='bsu';$('taxField').hidden=id!=='bsu';$('examples').replaceChildren(el('p','Eksempler innen '+t.title.toLowerCase()+':','hint'));for(const q of t.questions){const b=button(q,()=>{$('question').value=q;search();});b.className='example-button';$('examples').append(b);} $('matchStatus').textContent='Valgt tema: '+t.title+'. Fyll inn det du vil nedenfor, og vis vurderingen. Spørsmålet brukes bare til å finne tema; eksemplene deler samme grunnsvar.';}
function search(){dirty();selected=null;$('answerButton').disabled=true;$('answerButton').textContent='Bekreft et tema først';for(const b of document.querySelectorAll('[data-topic]'))b.setAttribute('aria-pressed','false');const ids=V.findTopics($('question').value);$('matches').replaceChildren();$('matchStatus').textContent=ids.length?'Dette kan passe. Velg temaet du mener:':'Jeg fant ikke et sikkert tema. Velg et av temaene nedenfor. Veilederen kan ikke svare på alt.';for(const id of ids){const t=V.topics.find(t=>t.id===id),b=button(t.title,()=>choose(id));b.dataset.topic=id;b.setAttribute('aria-pressed','false');$('matches').append(b);}}
for(const t of V.topics){const b=button(t.title,()=>choose(t.id));b.dataset.topic=t.id;b.setAttribute('aria-pressed','false');$('topics').append(b);}
$('questionForm').addEventListener('submit',e=>{e.preventDefault();search();});$('question').addEventListener('input',()=>{dirty();selected=null;$('matches').replaceChildren();$('answerButton').disabled=true;$('answerButton').textContent='Finn og bekreft tema på nytt';$('matchStatus').textContent='Spørsmålet er endret. Finn tema på nytt, eller velg et tema nedenfor.';for(const b of document.querySelectorAll('[data-topic]'))b.setAttribute('aria-pressed','false');});
$('profileForm').addEventListener('input',dirty);$('profileForm').addEventListener('change',dirty);
$('profileForm').addEventListener('submit',e=>{e.preventDefault();if(!selected)return;const profile=Object.fromEntries(new FormData($('profileForm')));$('formError').hidden=true;let a;try{a=V.answer(selected,profile);}catch(err){$('formError').textContent=err.message;$('formError').hidden=false;return;}
const out=$('answer');out.replaceChildren();$('answerTitle').textContent=a.title;
const used=el('div','','answer-profile');used.append(el('strong','Opplysninger i denne vurderingen'));const list=el('ul');const labels={buffer:{yes:'Du har buffer',no:'Du mangler buffer'},debt:{yes:'Du har dyr gjeld',no:'Du har ikke dyr gjeld'},income:{stable:'Stabil inntekt',uncertain:'Usikker inntekt'},risk:{low:'Ønsker å unngå store fall',medium:'Tåler noe uro',high:'Tåler store svingninger'},discipline:{automatic:'Automatisk sparing',flexible:'Varierende sparebeløp'},fixed:{yes:'Boliglån med fastrente',no:'Boliglån uten fastrente'},owner:{yes:'Eier bolig',no:'Eier ikke bolig'},tax:{yes:'Oppgir tilstrekkelig skatt for BSU-fradrag',no:'Lite eller ingen skatt'}};
if(a.profile.age!==null)list.append(el('li','Alder: '+a.profile.age+' år'));if(a.profile.years!==null)list.append(el('li','Til bruk: '+a.profile.years+' år'));for(const [key,values]of Object.entries(labels)){if(key==='fixed'&&selected!=='mortgage'||['owner','tax'].includes(key)&&selected!=='bsu')continue;if(a.profile[key])list.append(el('li',values[a.profile[key]]));}if(!list.children.length)list.append(el('li','Ingen personlige opplysninger oppgitt. Svaret er generelt.'));used.append(list);out.append(used);
if(a.missing.length)out.append(el('p','Noen forhold er ikke oppgitt. Svaret forutsetter ikke at du har buffer, stabil inntekt eller økonomi til å tåle tap.','hint'));
for(const part of a.parts){const section=el('section','','answer-part');section.append(el('h3',part.title),el('p',part.text));out.append(section);}
const d=el('details');d.open=true;d.append(el('summary','Kilder og forutsetninger'));d.append(el('p','Kontrollert 22. oktober 2026. Kildene oppdateres ikke automatisk her. Sjekk gjeldende vilkår før du handler. Tersklene under 5, 5–10 og minst 10 år er grove redaksjonelle inndelinger, ikke garantier eller offisielle grenser.','hint'));const ul=el('ul','','source-list');for(const s of a.sources){const li=el('li'),link=el('a',s.title);link.href=s.url;link.target='_blank';link.rel='noopener noreferrer';li.append(link);ul.append(li);}d.append(ul,el('p','Kildene underbygger de generelle prinsippene. Sammenstillingen og tilpasningen til valgene dine er Spareverksteds egne. Kildene har ikke godkjent veilederen.','hint'));if(selected==='children')d.append(el('p','Barnesparing: Statsforvalterens lenkede side er arkivert. Bruk svaret som en oversikt, og avklar gjeldende forvaltningsregler direkte med Statsforvalteren før større gaver.','ask-stale'));out.append(d);hasAnswer=true;$('answerTitle').focus();
});
$('resetGuidance').addEventListener('click',()=>{$('profileForm').reset();$('questionForm').reset();selected=null;hasAnswer=false;$('matches').replaceChildren();$('examples').replaceChildren();$('matchStatus').textContent='Alt er tømt.';$('changed').textContent='';$('formError').hidden=true;for(const b of document.querySelectorAll('[data-topic]'))b.setAttribute('aria-pressed','false');for(const id of ['fixedField','ownerField','taxField'])$(id).hidden=true;$('answerButton').disabled=true;$('answerButton').textContent='Velg et tema først';$('answerTitle').textContent='Velg et tema for å begynne';$('answer').replaceChildren(el('p','Du får en forklaring, relevante forbehold og lenker til kildene.'));$('question').focus();});
})();
